create table announcement (active bit not null, pinned bit, created_at datetime(6) not null, id bigint not null auto_increment, published_at datetime(6), updated_at datetime(6), version bigint, badge varchar(60), title varchar(220) not null, title_mr varchar(220), slug varchar(240) not null, image_url varchar(400), link_url varchar(400), summary varchar(600), body TEXT, status enum ('ARCHIVED','DRAFT','PUBLISHED') not null, primary key (id)) engine=InnoDB;
create table app_user (enabled bit not null, created_at datetime(6) not null, id bigint not null auto_increment, last_login_at datetime(6), updated_at datetime(6), version bigint, username varchar(60) not null, password varchar(100) not null, email varchar(160), full_name varchar(160), role enum ('ROLE_ADMIN','ROLE_DOCTOR','ROLE_RECEPTIONIST') not null, primary key (id)) engine=InnoDB;
create table appointment (amount_payable decimal(10,2), appointment_date date not null, reminder_sent bit, slot_end time(6) not null, slot_start time(6) not null, created_at datetime(6) not null, doctor_id bigint, facility_id bigint, health_package_id bigint, id bigint not null auto_increment, patient_id bigint not null, speciality_id bigint, updated_at datetime(6), version bigint, payment_mode varchar(30), source varchar(30), reference_no varchar(32) not null, cancellation_reason varchar(400), symptoms varchar(1000), internal_notes TEXT, service_type enum ('HEALTH_CHECKUP','HOME_CARE','LAB_TEST','OPD_CONSULTATION','SECOND_OPINION','SURGERY_PLANNING','TELE_CONSULTATION') not null, status enum ('CANCELLED','CHECKED_IN','COMPLETED','CONFIRMED','NO_SHOW','PENDING','RESCHEDULED') not null, visit_mode enum ('HOME_VISIT','IN_HOSPITAL','VIDEO') not null, primary key (id)) engine=InnoDB;
create table award (active bit not null, sort_order integer, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), version bigint, award_year varchar(20), icon_key varchar(60), issuer varchar(200), title varchar(200) not null, image_url varchar(400), description varchar(600), primary key (id)) engine=InnoDB;
create table blog (featured bit, read_minutes integer, created_at datetime(6) not null, id bigint not null auto_increment, published_at datetime(6), updated_at datetime(6), version bigint, view_count bigint, category varchar(80), author varchar(120), title varchar(220) not null, title_mr varchar(220), slug varchar(240) not null, tags varchar(300), image_url varchar(400), excerpt varchar(500), content TEXT, status enum ('ARCHIVED','DRAFT','PUBLISHED') not null, primary key (id)) engine=InnoDB;
create table doctor (active bit not null, consultation_fee decimal(10,2), experience_years integer, featured bit, rating float(53), review_count integer, sort_order integer, teleconsult_enabled bit, created_at datetime(6) not null, facility_id bigint, id bigint not null auto_increment, speciality_id bigint, updated_at datetime(6), version bigint, registration_no varchar(60), designation varchar(120), languages varchar(120), name varchar(160) not null, slug varchar(180) not null, qualifications varchar(200), photo_url varchar(400), areas_of_expertise varchar(600), bio TEXT, primary key (id)) engine=InnoDB;
create table doctor_leave (leave_date date not null, created_at datetime(6) not null, doctor_id bigint not null, id bigint not null auto_increment, updated_at datetime(6), version bigint, reason varchar(200), primary key (id)) engine=InnoDB;
create table doctor_schedule (active bit not null, end_time time(6) not null, max_patients_per_slot integer, slot_minutes integer, start_time time(6) not null, teleconsult bit, created_at datetime(6) not null, doctor_id bigint not null, facility_id bigint, id bigint not null auto_increment, updated_at datetime(6), version bigint, day_of_week enum ('FRIDAY','MONDAY','SATURDAY','SUNDAY','THURSDAY','TUESDAY','WEDNESDAY') not null, primary key (id)) engine=InnoDB;
create table enquiry (created_at datetime(6) not null, facility_id bigint, id bigint not null auto_increment, updated_at datetime(6), version bigint, status varchar(20) not null, enquiry_type varchar(30), phone varchar(30), assigned_to varchar(120), email varchar(160), name varchar(160) not null, source_page varchar(200), subject varchar(200), resolution_note varchar(1000), message TEXT, primary key (id)) engine=InnoDB;
create table facility (active bit not null, bed_count integer, is_headquarter bit, latitude float(53), longitude float(53), rating float(53), review_count integer, sort_order integer, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), version bigint, pincode varchar(20), emergency_phone varchar(30), phone varchar(30), city varchar(120), district varchar(120), state varchar(120), email varchar(160), name varchar(160) not null, name_mr varchar(160), slug varchar(180) not null, hours_text varchar(200), address_line varchar(300), amenities varchar(400), image_url varchar(400), facility_type enum ('CLINIC','DIAGNOSTIC_CENTRE','MAIN_HOSPITAL','PHARMACY'), primary key (id)) engine=InnoDB;
create table health_condition (active bit not null, sort_order integer, created_at datetime(6) not null, id bigint not null auto_increment, speciality_id bigint, updated_at datetime(6), version bigint, icon_key varchar(60), name varchar(120) not null, name_mr varchar(120), slug varchar(140) not null, primary key (id)) engine=InnoDB;
create table health_package (active bit not null, fasting_required bit, featured bit, home_collection bit, list_price decimal(10,2), max_age integer, min_age integer, price decimal(10,2) not null, report_hours integer, sort_order integer, test_count integer, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), version bigint, gender_suitability varchar(20), tier varchar(30), icon_key varchar(60), tagline varchar(60), tagline_mr varchar(60), name varchar(160) not null, name_mr varchar(160), slug varchar(180) not null, description_mr TEXT, includes TEXT, description TEXT, primary key (id)) engine=InnoDB;
create table hero_slide (active bit not null, sort_order integer, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), version bigint, art_key varchar(60), eyebrow varchar(60), cta_label varchar(80), secondary_cta_label varchar(80), gradient varchar(200), headline varchar(220) not null, headline_mr varchar(220), cta_url varchar(300), secondary_cta_url varchar(300), background_image_url varchar(400), subheadline varchar(400), subheadline_mr varchar(400), primary key (id)) engine=InnoDB;
create table lab_test (active bit not null, fasting_required bit, home_collection bit, price decimal(10,2) not null, report_hours integer, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), version bigint, category varchar(80), sample_type varchar(80), name varchar(160) not null, name_mr varchar(160), slug varchar(180) not null, parameters varchar(400), primary key (id)) engine=InnoDB;
create table patient (age integer, consent_email bit, consent_sms bit, date_of_birth date, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), version bigint, pincode varchar(20), phone varchar(30) not null, city varchar(120), email varchar(160), full_name varchar(160) not null, address varchar(300), allergies varchar(400), medical_notes TEXT, gender enum ('FEMALE','MALE','OTHER','UNDISCLOSED'), primary key (id)) engine=InnoDB;
create table procedure (active bit not null, indicative_cost integer, sort_order integer, stay_days integer, created_at datetime(6) not null, id bigint not null auto_increment, speciality_id bigint, updated_at datetime(6), version bigint, icon_key varchar(60), name varchar(160) not null, name_mr varchar(160), slug varchar(180) not null, summary TEXT, primary key (id)) engine=InnoDB;
create table quick_link (active bit not null, sort_order integer, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), version bigint, link_group varchar(40), icon_key varchar(60), label varchar(120) not null, label_mr varchar(120), description varchar(240), description_mr varchar(240), link_url varchar(300) not null, primary key (id)) engine=InnoDB;
create table speciality (active bit not null, featured bit, sort_order integer, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6), version bigint, accent_color varchar(9), icon_key varchar(60), name varchar(120) not null, name_mr varchar(120), slug varchar(140) not null, summary TEXT, primary key (id)) engine=InnoDB;
create table success_story (active bit not null, featured bit, created_at datetime(6) not null, doctor_id bigint, id bigint not null auto_increment, published_at datetime(6), speciality_id bigint, updated_at datetime(6), version bigint, video_id varchar(40), patient_city varchar(120), patient_label varchar(120), title varchar(240) not null, slug varchar(260) not null, image_url varchar(400), summary varchar(600), primary key (id)) engine=InnoDB;
create table testimonial (active bit not null, rating integer, sort_order integer, created_at datetime(6) not null, id bigint not null auto_increment, speciality_id bigint, updated_at datetime(6), version bigint, city varchar(120), patient_name varchar(120) not null, relation varchar(200), quote varchar(1000), primary key (id)) engine=InnoDB;
create index idx_announcement_published on announcement (status, published_at);
alter table announcement add constraint idx_announcement_slug unique (slug);
alter table app_user add constraint idx_user_username unique (username);
create index idx_appt_doctor_date on appointment (doctor_id, appointment_date);
create index idx_appt_patient on appointment (patient_id);
create index idx_appt_status on appointment (status);
create index idx_appt_date on appointment (appointment_date);
alter table appointment add constraint uk_appt_slot unique (doctor_id, appointment_date, slot_start, visit_mode);
alter table appointment add constraint idx_appt_reference unique (reference_no);
create index idx_blog_status_published on blog (status, published_at);
alter table blog add constraint idx_blog_slug unique (slug);
create index idx_doctor_speciality on doctor (speciality_id);
create index idx_doctor_facility on doctor (facility_id);
create index idx_doctor_active on doctor (active);
alter table doctor add constraint idx_doctor_slug unique (slug);
create index idx_leave_doctor_date on doctor_leave (doctor_id, leave_date);
create index idx_schedule_doctor_day on doctor_schedule (doctor_id, day_of_week);
create index idx_schedule_facility on doctor_schedule (facility_id);
alter table doctor_schedule add constraint uk_schedule unique (doctor_id, day_of_week, start_time);
create index idx_enquiry_status on enquiry (status);
create index idx_enquiry_created on enquiry (created_at);
create index idx_facility_city on facility (city);
alter table facility add constraint idx_facility_slug unique (slug);
alter table health_condition add constraint idx_condition_slug unique (slug);
create index idx_package_featured on health_package (featured);
alter table health_package add constraint idx_package_slug unique (slug);
create index idx_hero_active_order on hero_slide (active, sort_order);
create index idx_labtest_category on lab_test (category);
alter table lab_test add constraint idx_labtest_slug unique (slug);
create index idx_patient_email on patient (email);
alter table patient add constraint idx_patient_phone unique (phone);
create index idx_procedure_speciality on procedure (speciality_id);
alter table procedure add constraint idx_procedure_slug unique (slug);
create index idx_quicklink_group on quick_link (link_group, sort_order);
create index idx_speciality_active on speciality (active);
alter table speciality add constraint idx_speciality_slug unique (slug);
alter table success_story add constraint idx_story_slug unique (slug);
